import {map} from 'rxjs/operators';
import {createApiAdapter} from './adapter/createApiAdapter';
import {IExternalMessage, IExternalTransportAdapter, ITransportAdapterMeta} from './interface';
import {sendRequest} from "./_helpers/sendRequest";
import {Observable} from "rxjs";
import {isErrorResponse} from "./_helpers/isErrorResponse";
import {ILogger} from "@veksa/logger";

interface IClientAdapterParams {
    logger: ILogger;
}

export const createClientAdapter = (params: IClientAdapterParams): IExternalTransportAdapter => {
    const {logger} = params;

    const adapter = createApiAdapter({type: 'message-to-host', logger});

    const send = (message: IExternalMessage, meta?: ITransportAdapterMeta): Observable<IExternalMessage['payload']> => {
        return sendRequest<IExternalMessage['payload']>(adapter, message, meta).pipe(
            map(response => {
                if (isErrorResponse(response)) {
                    throw response;
                }

                return response.payload as IExternalMessage['payload'];
            }),
        );
    };

    return {
        type: 'external',
        data$: adapter.data$,
        event$: adapter.event$,
        send,
        destroy: adapter.destroy,
    };
};
