import {Observable} from 'rxjs';
import {IAdapter, IExternalMessage, ITransportAdapterMeta} from '../interface';
import {v4} from "uuid";

export const sendRequest = <Response extends object>(
    adapter: IAdapter,
    message: IExternalMessage,
    meta?: ITransportAdapterMeta,
): Observable<IExternalMessage> => {
    const clientMsgId = message.clientMsgId
        ? message.clientMsgId
        : v4();

    return new Observable<IExternalMessage<Response>>(message$ => {
        if (!meta?.completed) {
            adapter.add(clientMsgId);
        }

        const subscription = adapter.data$.subscribe(data => {
            if (data.clientMsgId === clientMsgId) {
                message$.next({
                    payload: data.payload as Response,
                    payloadType: data.payloadType,
                    clientMsgId,
                });
            }
        });

        try {
            adapter.send({
                payload: message.payload,
                payloadType: message.payloadType,
                clientMsgId,
            });

            if (meta?.completed) {
                adapter.remove(clientMsgId);

                subscription.unsubscribe();
                message$.next({} as IExternalMessage<Response>);
                message$.complete();
            }
        } catch (error) {
            adapter.remove(clientMsgId);

            subscription.unsubscribe();
            message$.error(error);
        }

        return () => {
            adapter.remove(clientMsgId);

            subscription.unsubscribe();
            message$.complete();
        };
    })
};
