import {share, Subject, switchMap} from 'rxjs';
import {catchError} from 'rxjs/operators';
import {createApiConnector} from '../connector/createApiConnector';
import {IAdapter, IExternalMessage} from '../interface';
import {ILogger} from "@veksa/logger";

interface IApiAdapterParams {
    type: 'message-to-host' | 'message-from-host',
    frame?: HTMLIFrameElement;
    logger: ILogger;
    id?: string;
}

export const createApiAdapter = (params: IApiAdapterParams): IAdapter => {
    const {type, frame, logger, id} = params;

    const messages: Record<string /* clientMsgId */, string /* clientMsgId */> = {};

    const data$ = new Subject<IExternalMessage>();
    const event$ = new Subject<IExternalMessage>();
    const message$ = new Subject<IExternalMessage>();

    const subscription = createApiConnector<IExternalMessage>(type, frame, id).pipe(
        switchMap(getResponses => {
            if (type === 'message-to-host') {
                logger.info('connected to host');
            } else {
                logger.info('connected to client');
            }

            return getResponses(message$);
        }),
        catchError(error => {
            logger.info('socket error', error);

            return [];
        }),
    ).subscribe({
        next: message => {
            if (message !== undefined) {
                if (!Object.keys(messages).includes(message.clientMsgId)) {
                    logger.event(message);
                    event$.next(message);
                } else {
                    logger.response(message);
                    data$.next(message);
                }
            } else {
                logger.error('empty message');
            }
        },
        error: (error: unknown) => {
            logger.error('connection error', error);
        },
        complete: () => {
            logger.info('connection closed');
        },
    });

    const add = (clientMsgId: string) => {
        messages[clientMsgId] = clientMsgId;
    };

    const remove = (clientMsgId: string) => {
        delete messages[clientMsgId];
    };

    const destroy = () => {
        subscription.unsubscribe();
    }

    const send = (message: IExternalMessage) => {
        if (!Object.keys(messages).includes(message.clientMsgId)) {
            logger.event(message);
        } else {
            logger.request(message);
        }

        message$.next(message);
    };

    return {
        data$: data$.asObservable().pipe(share()),
        event$: event$.asObservable().pipe(share()),
        add,
        remove,
        send,
        destroy,
    };
};
